for n in range(1, 100):
    s = '>' + '1' * 10 + '2' * n + '3' * 10
    while '>1' in s or '>2' in s or '>3' in s:
        if '>1' in s:
            s = s.replace('>1', '22>', 1)
        if '>2' in s:
            s = s.replace('>2', '2>', 1)
        if '>3' in s:
            s = s.replace('>3', '1>2', 1)
    if sum(int(c) for c in s if c.isdigit()) == 100:
        print(n)
        break

